"""Generate the static curriculum page; retain content without JavaScript."""
import json
from pathlib import Path
from html import escape as e
ROOT=Path(__file__).resolve().parents[1]
data=json.loads((ROOT/'ensino-medio/curriculo.json').read_text())
blocks={0:'Ampliação na etapa',1:'1 · Medidas, linguagem e algoritmos',2:'2 · Funções e modelos',3:'3 · Crescimento, música e finanças',4:'4 · Dados, contagem e decisões'}
labels={'relacionado':'Recurso relacionado','parcial':'Base parcial','lacuna':'Novo roteiro em papel','novo':'Novo laboratório'}
cards=[]
for s in data['skills']:
 r=data['resources'][s['resource']]
 link=f'<a href="{e(r["href"])}">{e(r["label"])}</a>' if r['href'] else e(r['label'])
 cards.append(f'''<article class="skill" id="{s['code']}" data-block="{s['block']}" data-status="{s['status']}">
 <div class="skill-top"><a class="code" href="#{s['code']}">{s['code']}</a><span class="badge {s['status']}">{labels[s['status']]}</span></div>
 <h3>{e(s['title'])}</h3><p>{e(s['summary'])}</p><p class="placement">{blocks[s['block']]}</p>
 <details><summary>Ver conexão, atividade e avaliação</summary>
 <h4>O que sincroniza com o site</h4><p>{link}. {e(s['relation'])}</p><p class="muted">{e(r['note'])}.</p>
 <h4>Construir e investigar</h4><p>{e(s['activity'])}</p>
 <h4>Pergunta para conferir</h4><p>{e(s['question'])}</p>
 <div class="response" aria-hidden="true"></div>
 <details class="answer"><summary>Conferência comentada</summary><p>{e(s['answer'])}</p></details>
 <h4>Evidência de aprendizagem</h4><p>{e(s['evidence'])}</p>
 <a class="source" href="{data['source']}#page={s['page']}">Consultar texto oficial · página impressa {s['page']-1}</a>
 </details></article>''')
html='''<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Ensino Médio · Matemática e BNCC · Leo Sardinha.Math</title>
<meta name="description" content="43 habilidades de Matemática da BNCC, conexões com os jogos, atividades com materiais reutilizados e percursos sugeridos para o 1º ano.">
<link rel="stylesheet" href="../assets/site.css"><link rel="stylesheet" href="style.css?v=1">
<script defer src="math.js?v=1"></script><script defer src="app.js?v=1"></script></head>
<body><a class="skip" href="#conteudo">Pular para o conteúdo</a>
<header class="site-header"><nav class="nav" aria-label="Navegação principal"><a class="brand" href="../index.html">Leo Sardinha<span>.Math</span></a><div class="menu"><a href="../educacao.html">Educação</a><a href="../professor/">Área do Professor</a><a href="#mapa">Mapa BNCC</a><a href="#laboratorio">Funções</a></div></nav></header>
<main class="wrap" id="conteudo"><header class="page-head"><p class="eyebrow">Matemática e suas Tecnologias</p><h1 class="page-title">Do jogo à<br>investigação.</h1><p class="lead">Um mapa do Ensino Médio para escolher o recurso, construir uma atividade e observar o que o estudante aprendeu.</p><div class="metrics"><span><b>43</b> habilidades mapeadas</span><span><b>4</b> percursos sugeridos</span><span><b>43</b> roteiros complementares</span></div></header>
<aside class="notice"><strong>1º ano é uma proposta de percurso, não uma lista oficial separada.</strong> A BNCC apresenta as habilidades EM13MAT para toda a etapa, sem seriação. Os percursos abaixo são sugestões para o 1º ano: ajuste ao currículo da rede, aos pré-requisitos e ao tempo disponível. Não é necessário trabalhar os 35 vínculos dos percursos em um único ano nem em um projeto de dois meses. As outras 8 habilidades permanecem no mapa como ampliação da etapa. <a href="https://basenacionalcomum.mec.gov.br/images/BNCC_EI_EF_110518_versaofinal_site.pdf#page=531">Fonte: BNCC, p. 530</a>.</aside>
<section aria-labelledby="percursos"><h2 id="percursos">Por onde começar no 1º ano</h2><p>Quatro entradas articuladas, sem duração obrigatória. Cada percurso reúne possibilidades; o professor seleciona as habilidades que correspondem ao planejamento da escola.</p><div class="paths">
<a href="#mapa" data-pick="1"><small>Percurso 1</small><h3>Medir, representar, programar</h3><p>Diagnóstico de razões e unidades; recortes, crivo e algoritmos. Produto: solução explicada para uma demanda da escola.</p></a>
<a href="#mapa" data-pick="2"><small>Percurso 2</small><h3>Descobrir funções</h3><p>Da tabela à expressão e ao gráfico: retas, parábolas, sistemas, PA e modelos por faixas.</p></a>
<a href="#mapa" data-pick="3"><small>Percurso 3</small><h3>Crescer e comparar</h3><p>Tabuleiro de grãos, afinação musical, PG, exponenciais, logaritmos e orçamento.</p></a>
<a href="#mapa" data-pick="4"><small>Percurso 4</small><h3>Investigar dados e chances</h3><p>Barcos de papelão, contagem e sorteio; pesquisa amostral, gráficos, centro e dispersão.</p></a></div></section>
<section class="teaching"><h2>Construir antes de formalizar</h2><p>Use papel de rascunho, embalagens limpas, tampinhas e barbante reaproveitado. Cada dupla constrói seu modelo, registra uma previsão, testa e explica. Cor deve vir acompanhada de forma ou símbolo. Sem vidro e sem necessidade de impressão colorida.</p><p><strong>Encontro de 40 minutos:</strong> 5 min para a pergunta, 15 min de construção, 10 min de investigação, 5 min de registro e 5 min de conferência e organização. Um roteiro pode exigir vários encontros: não significa domínio de uma habilidade em 40 minutos.</p><p>Para um projeto de dois meses, reserve aproximadamente 8 encontros e escolha um conjunto pequeno de habilidades relacionadas. Pesquisas, programação e planilhas exigem etapas adicionais. O papel prepara as habilidades digitais, mas não substitui sua implementação; organize acesso compartilhado quando necessário.</p></section>
<section id="laboratorio" class="lab" aria-labelledby="lab-title"><p class="eyebrow">Novo recurso · funções</p><h2 id="lab-title">Uma fórmula. Três representações.</h2><p>Altere o modelo e compare expressão, tabela e gráfico. Antes de calcular, preveja a forma e escolha um domínio que faça sentido para o problema.</p>
<noscript><p>Ative JavaScript para usar o explorador. Todos os roteiros e conferências abaixo continuam disponíveis.</p></noscript>
<form id="function-form"><div class="lab-controls"><label>Família<select id="family"><option value="linear">Afim · ax + b</option><option value="quadratic">Quadrática · ax² + bx + c</option><option value="exponential">Exponencial · a · qˣ</option><option value="logarithmic">Logarítmica · log_q(x)</option></select></label>
<label id="a-label">a<input id="coef-a" type="number" value="2" min="-10000" max="10000" step="any" required></label><label id="b-label">b<input id="coef-b" type="number" value="3" min="-10000" max="10000" step="any" required></label><label id="c-label" hidden>c<input id="coef-c" type="number" value="0" min="-10000" max="10000" step="any" required></label><label id="q-label" hidden>Base q<input id="base-q" type="number" value="2" min="0.0001" max="100" step="any" required></label>
<label>x inicial<input id="x-min" type="number" value="-4" min="-1000" max="1000" step="any" required></label><label>x final<input id="x-max" type="number" value="4" min="-1000" max="1000" step="any" required></label></div><button type="submit">Comparar representações</button></form>
<p id="lab-status" role="status"></p><p id="formula" class="formula"></p><div class="representations"><div><svg id="plot" viewBox="0 0 600 350" role="img" aria-labelledby="plot-title plot-description"><title id="plot-title">Gráfico da função</title><desc id="plot-description">A tabela ao lado apresenta valores da mesma função.</desc></svg><p class="muted">Os eixos se ajustam ao intervalo escolhido; compare as escalas ao trocar parâmetros. A linha representa um modelo contínuo, mesmo quando o contexto só admite índices inteiros.</p></div><div class="table-wrap"><table><caption>Valores amostrados no intervalo</caption><thead><tr><th scope="col">x</th><th scope="col">f(x)</th></tr></thead><tbody id="values"></tbody></table></div></div></section>
<section id="mapa" aria-labelledby="mapa-title"><h2 id="mapa-title">Encontre a habilidade e a atividade</h2><p>As descrições são sínteses autorais. Cada cartão aponta para o texto oficial e explica o alcance do recurso.</p><details class="legend"><summary>Como interpretar as conexões</summary><ul><li><strong>Recurso relacionado:</strong> já oferece parte central da investigação; precisa da ampliação e do registro indicados.</li><li><strong>Base parcial:</strong> funciona como contexto ou pré-requisito. Não atende sozinho à habilidade.</li><li><strong>Novo roteiro em papel:</strong> lacuna no acervo digital anterior; a atividade proposta está disponível no cartão.</li><li><strong>Novo laboratório:</strong> o explorador acima oferece apoio para a atividade, sem substituir modelagem e argumentação.</li></ul><p>Mapear uma habilidade não certifica que ela foi integralmente ensinada ou aprendida.</p></details>
<div class="filters"><label>Buscar código, tema ou recurso<input id="search" type="search" placeholder="Ex.: EM13MAT304, barcos, gráfico"></label><label>Percurso<select id="block"><option value="all">Toda a etapa · 43 habilidades</option value="priority">Possibilidades para o 1º ano</option value="1">1 · Medidas e algoritmos</option><option value="2">2 · Funções e modelos</option><option value="3">3 · Crescimento e finanças</option><option value="4">4 · Dados e decisões</option><option value="0">Ampliação na etapa</option></select></label><label>Conexão<select id="status"><option value="all">Todas as conexões</option value="relacionado">Recurso relacionado</option><option value="parcial">Base parcial</option><option value="lacuna">Novo roteiro em papel</option><option value="novo">Novo laboratório</option></select></label></div>
<div class="toolbar"><button id="clear" type="button">Limpar filtros</button><button id="expand" type="button">Abrir atividades visíveis</button><button id="print" type="button">Imprimir seleção</button><label><input id="with-answers" type="checkbox"> Incluir conferências na impressão</label></div><p id="results" role="status">43 habilidades disponíveis.</p><p class="muted">A impressão inclui somente os cartões filtrados. Sem filtros, imprime o mapa inteiro. Use a busca por código para uma única ficha.</p><div id="skills">__CARDS__</div><p id="empty" hidden>Nenhuma habilidade encontrada. Limpe os filtros ou tente outro termo.</p></section>
<section class="audit"><h2>O que fica como apoio ou aprofundamento</h2><p><strong>Bingo de Frações e 35 Camelos:</strong> recomposição de aprendizagens de frações, não cobertura direta de uma habilidade do Ensino Médio. <strong>Raízes e NCM/Difusão:</strong> contextos para discutir estratégias; jogar não equivale a implementar algoritmos.</p><p><strong>Calculus Royale, Ilha das Derivadas, Ilha do Cálculo e Bingo das Quádricas:</strong> aprofundamento. Derivadas, Lagrange e superfícies quádricas não são pré-requisitos deste percurso do 1º ano. O projeto de Cara a Cara Naval está proposto aqui em papel; não é anunciado como função já implementada no jogo digital.</p><p>As relações foram conferidas no conteúdo do site em 17/11/2026. O laboratório digital com acesso oculto não integra os links deste mapa.</p></section>
<footer class="page-footer"><p>Referência: BNCC homologada, Matemática e suas Tecnologias, competências 1 a 5, páginas impressas 533–541. Organização anual e atividades: propostas pedagógicas deste site.</p><a href="../educacao.html">← Voltar a Educação</a> · <a href="curriculo.json" download>Baixar mapa em JSON</a></footer></main><footer class="footer">Leo Sardinha.Math · Aprender, construir e argumentar</footer></body></html>'''
(ROOT/'ensino-medio/index.html').write_text(html.replace('__CARDS__','\n'.join(cards)))
